#nullable enable
using JetBrains.ReSharper.Psi;
using JetBrains.ReSharper.Psi.SourceGenerators;

namespace DotNetAnalysisAndRefactoringMcp;

/// <summary>
///   A file a source generator wrote: the generator, and the name it gave the file. The text answers name it where they
///   write a path for any other file: <c>[generated by Shapes.Generators.SwatchGenerator] Swatch.g.cs</c>.
/// </summary>
/// <remarks>
///   Rider holds such a file in memory, with no path, so its path can't say where it is. Until 2026-11-26 the answers
///   said only <c>[generated]</c> of a declaration there, and <c>find_usages</c> left out the usages there.
/// </remarks>
public sealed class GeneratedFile
{
   GeneratedFile(string? generator, string hintName)
   {
      Generator = generator;
      HintName = hintName;
   }

   /// <summary>
   ///   The generator's full type name, such as <c>Shapes.Generators.SwatchGenerator</c>; nothing for a file with no
   ///   path that Rider knows of no generator of.
   /// </summary>
   public string? Generator { get; }

   /// <summary>The name the generator gave the file, such as <c>Swatch.g.cs</c>.</summary>
   public string HintName { get; }

   /// <summary>
   ///   As the text answers name it: <c>[generated by Shapes.Generators.SwatchGenerator] Swatch.g.cs</c>, or
   ///   <c>[generated]</c> when Rider knows of no <see cref="Generator"/>.
   /// </summary>
   public string Name => Generator == null ? "[generated]" : $"[generated by {Generator}] {HintName}";

   /// <summary>The generated file <paramref name="file"/> is; nothing for a file with a path.</summary>
   public static GeneratedFile? Of(IPsiSourceFile file) =>
      file is ISourceGeneratorOutputFile generated ? new GeneratedFile(generated.GeneratorName, generated.HintName)
    : string.IsNullOrEmpty(file.GetLocation().FullPath) ? new GeneratedFile(null, file.Name)
    : null;

   /// <summary>What the text answers write where they write a file's full path: its <see cref="Name"/> for a generated file.</summary>
   public static string NameOrPathOf(IPsiSourceFile file) => Of(file)?.Name ?? file.GetLocation().FullPath;
}
